import{_ as i}from"./chunks/plugin-vue_export-helper.DlAUqK2U.js";import{c as a,o as t,af as n}from"./chunks/mermaid.DEOxUarQ.js";import"./chunks/cytoscape.C2CwDKBM.js";import"./chunks/dayjs.C32PoDnw.js";const y=JSON.parse('{"title":"Building Semantic Search on My Content","description":"Kent C. Dodds 在个人站点落地语义搜索的完整方案：分块策略、Hash 增量索引、过 fetch 检索与文档级合并（基于 Cloudflare Vectorize）。","frontmatter":{"title":"Building Semantic Search on My Content","description":"Kent C. Dodds 在个人站点落地语义搜索的完整方案：分块策略、Hash 增量索引、过 fetch 检索与文档级合并（基于 Cloudflare Vectorize）。","domain":"tech","tags":["tech","case","semantic-search","rag","vectorize"],"navOrder":76,"topicId":"cases-building-semantic-search","layer":"appendix","status":"case","nodeType":"evidence","owner":"learn-ai","lastVerified":"2026-09-01","listed":true},"headers":[],"relativePath":"zh/tech/appendices/cases/building-semantic-search.md","filePath":"zh/tech/appendices/cases/building-semantic-search.md","lastUpdated":1791123418000}'),e={name:"zh/tech/appendices/cases/building-semantic-search.md"};function h(l,s,p,k,r,d){return t(),a("div",null,[...s[0]||(s[0]=[n('<h1 id="building-semantic-search-on-my-content" tabindex="-1">Building Semantic Search on My Content <a class="header-anchor" href="#building-semantic-search-on-my-content" aria-label="Permalink to &quot;Building Semantic Search on My Content&quot;">​</a></h1><blockquote><p>来源：<a href="https://kentcdodds.com/blog/building-semantic-search-on-my-content" target="_blank" rel="noreferrer">Kent C. Dodds - Building Semantic Search on My Content</a></p></blockquote><h2 id="概述" tabindex="-1">概述 <a class="header-anchor" href="#概述" aria-label="Permalink to &quot;概述&quot;">​</a></h2><p>在个人内容站上构建语义搜索（Semantic Search）：理解查询语义而非关键词匹配。技术选型 <a href="https://developers.cloudflare.com/vectorize/" target="_blank" rel="noreferrer">Cloudflare Vectorize</a>（配合 Workers AI 生成 embedding）——选它因为 Cloudflare 提供完整的 AI 应用平台（Workers AI + AI Gateway + Vectorize），部署简单、生态完善。</p><p>主线概念（embedding、检索、RAG）见<a href="/zh/tech/04-grounding/embeddings-retrieval.html">嵌入与检索</a>与 <a href="/zh/tech/04-grounding/rag.html">RAG</a>；本页只保留工程实现的关键决策。</p><h2 id="索引架构" tabindex="-1">索引架构 <a class="header-anchor" href="#索引架构" aria-label="Permalink to &quot;索引架构&quot;">​</a></h2><p>核心流程：</p><ol><li><strong>分块（Chunk）</strong>：内容拆为重叠的块</li><li><strong>生成 Hash</strong>：为每块生成稳定 SHA-256</li><li><strong>跳过未变更</strong>：Hash 对比实现增量索引</li><li><strong>Embedding</strong>：调模型生成向量</li><li><strong>Upsert</strong>：写入 Vectorize</li></ol><h3 id="分块策略" tabindex="-1">分块策略 <a class="header-anchor" href="#分块策略" aria-label="Permalink to &quot;分块策略&quot;">​</a></h3><div class="language-javascript vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">javascript</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">const</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> chunkBodies</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;"> =</span><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;"> chunkTextRaw</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">(source, {</span></span>\n<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">    targetChars: </span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">2500</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">,    </span><span style="--shiki-light:#6A737D;--shiki-dark:#6A737D;">// 目标块大小</span></span>\n<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">    overlapChars: </span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">250</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">,   </span><span style="--shiki-light:#6A737D;--shiki-dark:#6A737D;">// 块间重叠</span></span>\n<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">    maxChunkChars: </span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">3500</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">, </span><span style="--shiki-light:#6A737D;--shiki-dark:#6A737D;">// 绝对上限（避免超过 embedding 模型输入限制）</span></span>\n<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">})</span></span></code></pre></div><p>为什么分块：embedding 模型有输入 token 限制；精细分块让检索命中「最相关的段落」而非整篇文档。为什么重叠：重要信息恰好落在块边界时不被切断。</p><h3 id="稳定-id-与增量索引" tabindex="-1">稳定 ID 与增量索引 <a class="header-anchor" href="#稳定-id-与增量索引" aria-label="Permalink to &quot;稳定 ID 与增量索引&quot;">​</a></h3><div class="language-javascript vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">javascript</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">const</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> vectorId</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;"> =</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> `${</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">docId</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">}:chunk:${</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">i</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">}`</span><span style="--shiki-light:#6A737D;--shiki-dark:#6A737D;">  // 稳定 ID：更新/删除具有确定性</span></span>\n<span class="line"><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">const</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> text</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;"> =</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> `Title: ${</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">title</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">}</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">\\n</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">URL: ${</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">url</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">}</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">\\n\\n</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">${</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">chunkBody</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">}`</span></span>\n<span class="line"><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">const</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> hash</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;"> =</span><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;"> sha256</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">(text)               </span><span style="--shiki-light:#6A737D;--shiki-dark:#6A737D;">// 内容 Hash</span></span>\n<span class="line"></span>\n<span class="line"><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">if</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;"> (oldHashesById.</span><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">get</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">(vectorId) </span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">===</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;"> hash) </span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">continue</span><span style="--shiki-light:#6A737D;--shiki-dark:#6A737D;">  // 未变化，跳过 embedding</span></span></code></pre></div><p>核心思想：<strong>Hash 没变 → 不重新 embedding</strong>，节省成本并加速索引。更新语义：文档变化 → Hash 变化 → 重新 embed → upsert；未变 → 跳过。</p><h2 id="搜索架构" tabindex="-1">搜索架构 <a class="header-anchor" href="#搜索架构" aria-label="Permalink to &quot;搜索架构&quot;">​</a></h2><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>查询 embedding → Vectorize 最近邻（过 fetch）→ 合并块级结果为文档级 → 按得分排序返回</span></span></code></pre></div><p><strong>过 fetch 策略</strong>：取 <code>safeTopK * 5</code> 个块级结果，因为同一文档可能命中多个块，合并后文档数会减少：</p><div class="language-javascript vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">javascript</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">const</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> safeTopK</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;"> =</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;"> Math.</span><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">max</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">(</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">1</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">, Math.</span><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">min</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">(</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">15</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">, Math.</span><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">floor</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">(topK)))</span></span>\n<span class="line"><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">const</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> rawTopK</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;"> =</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;"> Math.</span><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">min</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">(</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">15</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">, safeTopK </span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">*</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> 5</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">)  </span><span style="--shiki-light:#6A737D;--shiki-dark:#6A737D;">// 多取块，合并后裁剪</span></span></code></pre></div><p><strong>文档级合并</strong>：按 <code>type:slug</code> 聚合同一文档的多个块命中，保留得分最高的块作为该文档的代表结果，最后裁剪到 <code>safeTopK</code>。</p><h2 id="关键要点" tabindex="-1">关键要点 <a class="header-anchor" href="#关键要点" aria-label="Permalink to &quot;关键要点&quot;">​</a></h2><ol><li><strong>Chunk + Hash</strong>：稳定 ID 与内容 Hash 是高效增量索引的关键。</li><li><strong>纯向量检索</strong>：无需维护倒排索引，自然支持语义相似度。</li><li><strong>块级 → 文档级合并</strong>：解决向量库只返回块级匹配的问题，保证用户看到文档级结果。</li><li><strong>元数据随向量走</strong>：每条向量携带 title/url/snippet，检索结果可直接渲染。</li></ol>',21)])])}const F=i(e,[["render",h]]);export{y as __pageData,F as default};
